function busRows(){if(!editor)return[];const rows=new Set(editor.elements.filter(e=>e?.visible!==false&&e.type!=='sofor'&&e.type!=='arka-koltuk'&&e.properties?.konum!=='arka').map(e=>Number(e.row)||0));return[...rows].sort((a,b)=>a-b)}
